// === rem 适配（lib-flexible 思路） ===
// 需要在 <head> 中尽早执行，避免 FOUC
(function() {
  function setRem() {
    const docEl = document.documentElement;
    const width = docEl.clientWidth;
    // 设计稿 750px，分 10 份，1rem = 75px
    docEl.style.fontSize = (width / 750) * 100 + 'px';
  }
  setRem();
  window.addEventListener('resize', setRem);
})();

// === postcss.config.js（vw 适配 + autoprefixer） ===
// 安装：npm i postcss-px-to-viewport autoprefixer
module.exports = {
  plugins: {
    'postcss-px-to-viewport': {
      viewportWidth: 750,    // 设计稿宽度
      unitPrecision: 5,      // vw 值小数位
      viewportUnit: 'vw',
      minPixelValue: 1       // 小于 1px 不转换
    },
    autoprefixer: {}
  }
};

// === CSS Modules (React) ===
// styles.module.css
// .title { color: #1a1a1a; }
// .active { font-weight: 700; }
import styles from './styles.module.css';
function App() {
  return <h1 className={styles.title}>Hello</h1>;
}
// 编译后：<h1 class="title_abc123">Hello</h1>

// === Tailwind CSS ===
function Card() {
  return (
    <div className="bg-white rounded-lg shadow-md p-6 hover:shadow-lg transition-shadow">
      <h2 className="text-xl font-bold text-gray-800 mb-2">Title</h2>
      <p className="text-gray-600 leading-relaxed">Content</p>
    </div>
  );
}

/* === Cascade Layers（层叠治理） === */
@layer reset, base, components, utilities;
@layer reset { *, *::before, *::after { box-sizing: border-box; margin: 0; } }
@layer components { .btn { padding: 0.5rem 1rem; border-radius: 4px; } }
@layer utilities { .hidden { display: none; } }

/* === Container Queries === */
.card-container { container-type: inline-size; }
@container (min-width: 400px) {
  .card { grid-template-columns: 1fr 1fr; }
}
@container (max-width: 399px) {
  .card { grid-template-columns: 1fr; }
}

/* === 媒体查询断点 === */
@media (max-width: 768px) {
  .sidebar { display: none; }
  .main { width: 100%; }
}
@media (min-width: 1200px) {
  .container { max-width: 1140px; margin: 0 auto; }
}
